local config = {
  ui_story_30540401_1_dialog_content = "Tidak apa-apa. Utarakan pikiranmu.",
  ui_story_30540401_2_dialog_content = "Sebenarnya, tidak penting. Kau baru pulang setelah bekerja seharian, jadi aku ingin tahu apa ada yang bisa kulakukan untukmu.",
  ui_story_30540401_3_dialog_content = "Kau terganggu oleh pikiranku itu?",
  ui_story_30540401_4_option_content = "Aku cuma tidak terbiasa dengannya saja",
  ui_story_30540401_5_dialog_content = "Bagaimana cara mengatakannya... Aku cenderung sering menemui orang \"<color=#FFB400>dengan sikap yang unik</color>\".",
  ui_story_30540401_6_dialog_content = "Singkatnya, aku terbiasa ditindas sampai-sampai rasanya aneh kalau ada orang yang memperlakukanku dengan sangat baik.",
  ui_story_30540401_7_dialog_content = "Oh, aku sangat menghargainya, tentu saja!",
  ui_story_30540401_8_option_content = "Sama sekali tidak. Aku sangat tersentuh!",
  ui_story_30540401_9_dialog_content = "Teman yang peduli sangat sulit ditemukan!",
  ui_story_30540401_10_dialog_content = "Jujur, menurutku orang yang peduli sudah langka sekarang ini.",
  ui_story_30540401_11_dialog_content = "Kau belum cukup tua untuk berbicara seolah-olah kau ketinggalan zaman...",
  ui_story_30540401_12_dialog_content = "Tidak, aku belum cukup tua, tapi aku ketinggalan zaman. Maksudku, aku lama hidup sendirian di Colossus...",
  ui_story_30540401_13_dialog_content = "Itu terlalu... Omong-omong, aku ingin melakukan sesuatu untukmu!",
  ui_story_30540401_14_dialog_content = "Aku sangat menghargai kepedulianmu!",
  ui_story_30540401_15_dialog_content = "Sepertinya ada surat yang datang untukku saat aku keluar. Aku akan mengambilnya dan kembali ke sini.",
  ui_story_30540401_16_dialog_content = "Oh, tidak perlu. Aku sudah mengambilnya untukmu!",
  ui_story_30540401_17_dialog_content = "Kau mengambil surat itu untukku? Kau baik dan pengertian sekali!",
  ui_story_30540401_18_dialog_content = "Ehem. Aku kebetulan mendengar Vice menyebutkannya, dan aku tahu kau sedang keluar, jadi...",
  ui_story_30540401_19_dialog_content = "Baiklah. Aku akan membacanya dulu.",
  ui_story_30540401_20_dialog_content = "Aku akan mengambilnya kalau kau mau membacanya sekarang! Duduklah dan jangan ke mana-mana!",
  ui_story_30540401_21_dialog_content = "Wow, aku hanya asal bicara dan dia langsung pergi!",
  ui_story_30540401_22_dialog_content = "Ini suratmu!",
  ui_story_30540401_23_dialog_content = "Eh, terima kasih!",
  ui_story_30540401_24_dialog_content = "Oh, akan kuambilkan minuman. Kau pasti haus dari perjalanan!",
  ui_story_30540401_25_dialog_content = "Kau mau apa, kopi atau teh?",
  ui_story_30540401_26_dialog_content = "Pasti enak. Sepertinya...",
  ui_story_30540401_27_option_content = "Teh",
  ui_story_30540401_28_dialog_content = "Teh adalah keahlianku! Kau lebih suka teh daripada kopi, seperti City Lord!",
  ui_story_30540401_29_option_content = "Kopi",
  ui_story_30540401_30_dialog_content = "Kopi adalah pilihan bagus! Aku suka minum kopi! Rasanya menenangkan!",
  ui_story_30540401_31_dialog_content = "Silakan, PlayerName!",
  ui_story_30540401_32_dialog_content = "Aduh!",
  ui_story_30540401_33_dialog_content = "Maaf! Aku tidak bermaksud menumpahkannya padamu!",
  ui_story_30540401_34_dialog_content = "Tidak apa-apa. Cuma sedikit. Aku bisa mengelapnya.",
  ui_story_30540401_35_dialog_content = "Tapi aku harus bertanya, kenapa kau bersemangat sekali untuk melayaniku hari ini?",
  ui_story_30540401_36_dialog_content = "Yah... Akhir-akhir ini aku belajar cara mengurus orang...",
  ui_story_30540401_37_dialog_content = "Oh? Kenapa tiba-tiba?",
  ui_story_30540401_38_dialog_content = "Karena... Sebagai <color=#FFB400>Nightwatch</color>, aku harus bisa melakukan semuanya!",
  ui_story_30540401_39_dialog_content = "Tidak ada urusan resmi yang harus kutangani belakangan ini, jadi aku membuat rencana untuk memperbaiki diri.",
  ui_story_30540401_40_option_content = "Apa itu Nightwatch?",
  ui_story_30540401_41_dialog_content = "Nightwatch adalah <color=#FFB400>pengawal rahasia</color> City Lord.",
  ui_story_30540401_42_dialog_content = "Aku mungkin pengawal, tapi bukan pengawal betulan yang menjaga City Lord, karena dia jauh lebih kuat daripada aku.",
  ui_story_30540401_43_dialog_content = "Dengan kata lain, kami adalah operasi khusus yang bekerja di malam hari untuk mengumpulkan informasi atau melakukan pembunuhan.",
  ui_story_30540401_44_dialog_content = "Apa yang kudengar ini rahasia menakutkan?",
  ui_story_30540401_45_dialog_content = "Kami mungkin pengawal rahasia, tapi keberadaan kami bukan rahasia.",
  ui_story_30540401_46_dialog_content = "Banyak orang sudah tahu tentang kami, tapi tidak tahu siapa saja anggotanya.",
  ui_story_30540401_47_dialog_content = "Tapi sekarang aku tahu kau...",
  ui_story_30540401_48_option_content = "Orang yang lebih baik? Seberapa lebih baik?",
  ui_story_30540401_49_dialog_content = "Setidaknya sebaik <color=#FFB400>Ms. Blanc</color>!",
  ui_story_30540401_50_dialog_content = "Dia bisa menangani segala macam misi dengan mudah, dan bisa tetap anggun bahkan saat membunuh!",
  ui_story_30540401_51_dialog_content = "Apa yang kudengar ini rahasia menakutkan?",
  ui_story_30540401_52_dialog_content = "Sebenarnya ini bukan rahasia. Ms. Blanc sendiri biasa membicarakannya, tapi tidak secara publik.",
  ui_story_30540401_53_dialog_content = "Tapi kau baru saja memberitahuku.",
  ui_story_30540401_54_dialog_content = "Hmm... Bukan masalah. Toh, kau punya jaringan cukup luas untuk mengetahuinya sendiri.",
  ui_story_30540401_55_dialog_content = "Tolong, jangan bilang-bilang kalau kau mendengarnya dariku.",
  ui_story_30540401_56_dialog_content = "Baiklah.",
  ui_story_30540401_57_dialog_content = "Sudah waktunya aku <color=#FFB400>masuk ke kamar</color>. Ada lagi?",
  ui_story_30540401_58_dialog_content = "Kenapa? Kau tidak bisa istirahat di sini saja?",
  ui_story_30540401_59_dialog_content = "Aku butuh privasi.",
  ui_story_30540401_60_dialog_content = "Oke... Apa kau mau menjawab satu pertanyaan sebelum pergi?",
  ui_story_30540401_61_dialog_content = "Menurutmu, seberapa baik performaku?",
  ui_story_30540401_62_option_content = "Kurasa cukup baik.",
  ui_story_30540401_63_dialog_content = "Dengan kata lain, kau cenderung \"puas\"?",
  ui_story_30540401_64_dialog_content = "\"Puas\" rasanya aneh, tapi menurutku kau sangat pengertian.",
  ui_story_30540401_65_option_content = "Hmm. Mungkin bisa lebih baik?",
  ui_story_30540401_66_dialog_content = "Pasti karena aku menumpahkan minuman padamu, 'kan?",
  ui_story_30540401_67_dialog_content = "Bukan. Itu tidak apa-apa. Jangan khawatir.",
  ui_story_30540401_68_dialog_content = "Wajar saja kita berbuat salah sesekali.",
  ui_story_30540401_69_dialog_content = "Tapi apa yang sebaiknya kulakukan kalau tidak sengaja berbuat salah?",
  ui_story_30540401_70_dialog_content = "Minta maaf saja dengan baik.",
  ui_story_30540401_71_dialog_content = "Oh, begitu... Kau mau mendengar kesalahan-kesalahan yang pernah kulakukan?",
  ui_story_30540401_72_dialog_content = "Sebenarnya, saat aku membawa surat itu ke <color=#FFB400>kamarmu</color>...",
  ui_story_30540401_73_dialog_content = "Kenapa? Aku tidak melihat ada yang salah dengan surat itu.",
  ui_story_30540401_74_dialog_content = "Bukan suratnya. Saat aku masuk ke kamarmu, kupikir agak berantakan...",
  ui_story_30540401_75_dialog_content = "Iya, sih. Aku tadi sangat terburu-buru jadi tidak sempat merapikannya.",
  ui_story_30540401_76_dialog_content = "Kupikir karena sedang senggang, aku akan merapikannya untukmu...",
  ui_story_30540401_77_dialog_content = "<color=#FFB400>Tapi aku malah membuatnya makin berantakan.</color>",
  ui_story_30540401_78_dialog_content = "...",
  ui_story_30540401_79_dialog_content = "...",
  ui_story_30540401_80_dialog_content = "<size=45>Hah?</size>",
  ui_story_30540401_81_dialog_content = "Aku ingin merapikannya sebelum kau pulang, tapi kau pulang lebih awal dari perkiraan! Maaf sekali!",
  ui_story_30540401_82_dialog_content = "Eh, bisa kau jelaskan apa yang kau lakukan...?",
  ui_story_30540401_83_dialog_content = "Aku merapikannya sedikit, melakukan sanitasi dengan kekuatan lentera, lalu menyeterika pakaianmu...",
  ui_story_30540401_84_dialog_content = "Lalu, kenapa kamarku tambah berantakan?",
  ui_story_30540401_85_dialog_content = "Beberapa pakaianmu rusak. Lantai dan dindingnya... sedikit retak.",
  ui_story_30540401_86_dialog_content = "Maaf sekali!",
  ui_story_30540401_87_dialog_content = "Sekarang aku paham kenapa kau bersemangat sekali melayaniku.",
  ui_story_30540401_88_dialog_content = "Untuk menebus kesalahanmu setelah merusak kamarku, 'kan?",
  ui_story_30540401_89_dialog_content = "Sayangnya, iya.",
  ui_story_30540401_90_dialog_content = "*Mengambil napas dalam-dalam dan terpaksa tersenyum*",
  ui_story_30540401_91_dialog_content = "Tidak apa-apa. Kau sudah berusaha keras untuk meminta maaf, jadi aku...",
  ui_story_30540401_92_dialog_content = "Tidak, aku tidak marah padamu.",
  ui_story_30540601_1_dialog_content = "Aku pulang...",
  ui_story_30540601_2_dialog_content = "\"Aku suka bekerja, benar itu!\"",
  ui_story_30540601_3_dialog_content = "\"Aku suka bekerja, bagaimana denganmu?\"",
  ui_story_30540601_4_dialog_content = "Kenapa para Firefly menyanyikan lagu yang aneh? Sebentar... Apa mereka... menari?!",
  ui_story_30540601_5_dialog_content = "Selamat datang kembali! Silakan taruh mantelmu di sini!",
  ui_story_30540601_6_dialog_content = "Oh, tolong lap sepatumu sebelum masuk kalau kamu tetap ingin mengenakannya.",
  ui_story_30540601_7_dialog_content = "Firefly! Lap sepatu!",
  ui_story_30540601_8_dialog_content = "\"Tolong gunakan kain ini untuk mengelap sepatumu.\"",
  ui_story_30540601_9_dialog_content = "Wah, kamu mengenakan pakaian baru! Tapi, anu... Apa yang sebenarnya terjadi di sini?",
  ui_story_30540601_10_dialog_content = "Aku sedang <color=#FFB400>bekerja</color>, PlayerName!",
  ui_story_30540601_11_dialog_content = "\"Bekerja\"? Kenapa kalian terus menyebut-nyebut soal \"bekerja\"?",
  ui_story_30540601_12_dialog_content = "Yah, jadi begini...",
  ui_story_30540601_13_dialog_content = "Seragam yang rapi dan disetrika dengan baik, dan secangkir kopi panas. Awal yang sempurna untuk bekerja keras seharian...",
  ui_story_30540601_14_dialog_content = "*Menghela napas* Hanya saja... ini hari liburku.",
  ui_story_30540601_15_dialog_content = "Semuanya baik-baik saja, Nadine?",
  ui_story_30540601_16_dialog_content = "Iya. Karena sangat sibuk bekerja, aku jadi terbiasa tetap sibuk sepanjang waktu.",
  ui_story_30540601_17_dialog_content = "Tapi, kalau tiba-tiba ada waktu libur dan tidak ada kegiatan... Rasanya agak aneh bagiku.",
  ui_story_30540601_18_dialog_content = "Kamu benar-benar pekerja keras dan berdedikasi, Nadine! Kamu juga menyukai pekerjaanmu!",
  ui_story_30540601_19_dialog_content = "Kalau saja...",
  ui_story_30540601_20_dialog_content = "Hmm? Ada yang kamu pikirkan, Vice?",
  ui_story_30540601_21_dialog_content = "Ehehe... Aku hanya berpikir... Kalau saja kamu bisa membantuku, aku akan sangat berterima kasih!",
  ui_story_30540601_22_dialog_content = "Membantu apa? Aku selalu bersedia membantu asalkan mampu.",
  ui_story_30540601_23_dialog_content = "Benarkah?",
  ui_story_30540601_24_dialog_content = "Begini... Aku baru saja mendapat misi yang mendesak, dan tak punya pilihan selain bergegas pergi.",
  ui_story_30540601_25_dialog_content = "Tapi, hari ini adalah giliranku berpatroli, dan PlayerName belum kembali...",
  ui_story_30540601_26_dialog_content = "Jadi, maukah kamu membantuku mengurus Colossus?",
  ui_story_30540601_27_dialog_content = "Kalau ada pertanyaan, aku sudah membuat \"buku panduan tugas patroli\" yang bisa kamu baca kapan pun!",
  ui_story_30540601_28_dialog_content = "Begitu rupanya... Aku mengerti. Serahkan saja padaku. Hati-hati saat menjalankan misi, ya.",
  ui_story_30540601_29_dialog_content = "Kamu sangat baik! Terima kasih banyak!",
  ui_story_30540601_30_dialog_content = "Oh, tak lama lagi akan ada seseorang yang mengantar barang. Jangan lupa menerimanya, ya?",
  ui_story_30540601_31_dialog_content = "Isinya pakaian baru.",
  ui_story_30540601_32_dialog_content = "Salah satunya adalah kejutan untukmu dari PlayerName. Tapi, kamu boleh membuka dan melihatnya!",
  ui_story_30540601_33_dialog_content = "Aku pergi dulu! Kuserahkan Colossus ini padamu sekarang!",
  ui_story_30540601_34_dialog_content = "Serahkan saja padaku. Akan kucoba semampuku!",
  ui_story_30540601_35_dialog_content = "Hmm... Menurut buku panduan ini, para Firefly mengurus sebagian besar tugas bersih-bersih di Colossus. Kalau begitu...",
  ui_story_30540601_35X_dialog_content = "Mungkin sebaiknya aku minum secangkir kopi agar lebih semangat?",
  ui_story_30540601_36_dialog_content = "<color=#e8d9bb>Nguuung!</color>",
  ui_story_30540601_38_dialog_content = "Aku sedang lengah saat Firefly itu terbang melewatiku, lalu aku tergelincir dan jatuh...",
  ui_story_30540601_39_dialog_content = "Dan menumpahkan kopi ke tubuhku sendiri. Aku terpaksa berganti pakaian dengan baju ini.",
  ui_story_30540601_40_dialog_content = "Cantik sekali... Aku berjanji tak akan mengotorinya! Apa aku benar-benar boleh memakainya?",
  ui_story_30540601_41_dialog_content = "Tentu saja boleh. Aku memang bermaksud menghadiahkannya padamu, kok.",
  ui_story_30540601_42_dialog_content = "Bagus sekali!",
  ui_story_30540601_43_dialog_content = "Omong-omong, ada apa dengan para Firefly itu? Barusan mereka semua menyanyi dan menari...",
  ui_story_30540601_44_dialog_content = "Aku menyesuaikan pengaturannya menurut buku panduan yang Vice tinggalkan.",
  ui_story_30540601_45_dialog_content = "Yang kamu lihat tadi adalah formasi siaga mereka.",
  ui_story_30540601_46_dialog_content = "Tapi, lagunya aneh...",
  ui_story_30540601_47_dialog_content = "Aku sering menyanyikan lagu itu. Semoga teman-teman kecil kita akan termotivasi dan makin giat bekerja di Colossus!",
  ui_story_30540601_48_dialog_content = "Aduh, kenapa kamu terus mengungkit soal \"kerja\" dan \"pekerjaan\", sih...?",
  ui_story_30540601_49_dialog_content = "Oh, benar! Aku masih harus menyelesaikan pemeriksaan kamar!",
  ui_story_30540601_50_dialog_content = "\"Pemeriksaan\"?",
  ui_story_30540601_51_dialog_content = "Oh, pelayan!",
  ui_story_30540601_52_dialog_content = "Aku mengerti.",
  ui_story_30540601_53_dialog_content = "Mengganti Mode: Sweeper.",
  ui_story_30540601_54_dialog_content = "Pemeriksaan kamar selesai. Barang selundupan telah disita.",
  ui_story_30540601_55_dialog_content = "B-barang selundupan?",
  ui_story_30540601_56_dialog_content = "Benar! Ada banyak aturan di buku panduan patroli Vice.",
  ui_story_30540601_57_dialog_content = "\"Untuk memastikan keselamatan semua penumpang Colossus, barang-barang berikut tidak diperbolehkan di dalam pesawat:\"",
  ui_story_30540601_58_dialog_content = "\"Barang yang mudah terbakar atau peledak...\"",
  ui_story_30540601_59_dialog_content = "Tiba-tiba aku jadi teringat pada orang-orang yang sering melanggar aturan ini...",
  ui_story_30540601_60_dialog_content = "\"Senjata berbahaya dan benda berbilah...\"",
  ui_story_30540601_61_dialog_content = "Lagi-lagi aku juga jadi teringat pada orang-orang yang sering melanggar aturan ini...",
  ui_story_30540601_62_dialog_content = "Nah? Aku baru selesai membaca aturan kedua, dan kamu mungkin bisa menyebutkan 12 nama orang yang terus melanggar aturan!",
  ui_story_30540601_63_dialog_content = "Kalau aturan saja dilanggar, orang tak akan menghormati satu sama lain, tahu?",
  ui_story_30540601_64_dialog_content = "Tentu saja, tapi...",
  ui_story_30540601_65_dialog_content = "Pelayan! Kita lanjut ke ruang lain!",
  ui_story_30540601_66_dialog_content = "Kuberi tahu, ya... bahkan Vice saja tidak menegakkan peraturan dengan sangat tegas...",
  ui_story_30540601_66X_dialog_content = "Eh... Halo? Pergi ke mana dia?",
  ui_story_30540601_67_dialog_content = "<color=#e8d9bb>Sepuluh menit kemudian...</color>",
  ui_story_30540601_68_dialog_content = "Di mana speaker milikku? Apa ada yang memindahkannya tanpa seizinku?",
  ui_story_30540601_69_dialog_content = "Di mana gergaji kecilku yang manis?",
  ui_story_30540601_70_dialog_content = "Sedang apa KAMU di sini?",
  ui_story_30540601_71_dialog_content = "Regina... Kamu yang mengambilnya, ya...?",
  ui_story_30540601_72_dialog_content = "Kamu bicara apa, sih? Kamu yang mencuri speaker milikku, 'kan?",
  ui_story_30540601_73_dialog_content = "Iri karena speaker milikku lebih tinggi dari kamu?!",
  ui_story_30540601_74_dialog_content = "Hah? Maksudmu, speaker jelek yang digunakan untuk pembukaan? Menyentuhnya saja aku ogah!",
  ui_story_30540601_75_dialog_content = "Apa katamu? Mau mengajak berkelahi?!",
  ui_story_30540601_76_dialog_content = "S-sebentar, sebentar... Tenangkan diri kalian! Barang kalian ada yang hilang, 'kan? Jangan-jangan...?",
  ui_story_30540601_77_dialog_content = "Kamu pikir aku takut padamu? Ayo kita selesaikan di sini sekarang!",
  ui_story_30540601_78_dialog_content = "Kamu jadi wasitnya, PlayerName!",
  ui_story_30540601_79_dialog_content = "Kenapa kalian masih saja bertengkar?! Aku tak mau ikut-ikutan...!",
  ui_story_30540601_80_dialog_content = "Kalau begitu, biar aku saja yang jadi wasitnya!",
  ui_story_30540601_81_dialog_content = "Eh? Suara itu... Bukankah itu...?",
  ui_story_30540601_82_dialog_content = "Pertama! Jadilah suar yang membimbing orang lain untuk maju!",
  ui_story_30540601_83_dialog_content = "Kedua! Setrika seragammu dan pastikan lipatannya rapi!",
  ui_story_30540601_84_dialog_content = "Ketiga! Selalu pertahankan etos kerja yang rajin!",
  ui_story_30540601_85_dialog_content = "Nadine sang \"<color=#FFB400>Patrol Kapten</color>\" datang untuk menjalankan tugas, dan mengawasi pertempuran yang sangat penting ini!",
  ui_story_30540601_86_dialog_content = "... Ada banyak hal yang tidak beres dengan situasi ini, aku bahkan tidak tahu harus mulai dari mana.",
  ui_story_30540601_87_dialog_content = "Omong-omong, kenapa kamu harus memperkenalkan diri seperti itu?",
  ui_story_30540601_88_dialog_content = "Yah, salah satu aturan di buku panduan Vice berbunyi \"pertahankan rasa kasih sayang dan harmoni di Colossus\"...",
  ui_story_30540601_89_dialog_content = "Memangnya apa hubungannya dengan perkenalan dirimu yang aneh barusan?!",
  ui_story_30540601_90_dialog_content = "Di buku panduan itu juga tertulis bahwa \"saat menengahi dua pihak yang bertikai, ingatlah untuk memperkenalkan diri sebagai mediator kedua belah pihak.\"",
  ui_story_30540601_91_dialog_content = "Aku sangat yakin yang dimaksud dengan \"menengahi\" dalam buku panduan itu berarti \"menghentikan pertikaian\"...",
  ui_story_30540601_92_dialog_content = "...",
  ui_story_30540601_93_dialog_content = "Lihat, PlayerName! Karena saking tercengangnya, mereka sampai lupa pada pertengkaran itu...",
  ui_story_30540601_94_dialog_content = "Itu bisa dianggap sebagai menghentikan pertikaian, 'kan?",
  ui_story_30540601_95_dialog_content = "... Omong-omong, saat melakukan pemeriksaan kamar yang kamu bilang tadi...",
  ui_story_30540601_96_dialog_content = "Apa kebetulan kamu sekalian menyita speaker Regina dan gergaji Barbara?",
  ui_story_30540601_97_dialog_content = "Ya, tadi aku memang menyingkirkan dua speaker besar dari Lounge.",
  ui_story_30540601_98_dialog_content = "Aku juga menyingkirkan gergaji yang kutemukan di sudut Cafe.",
  ui_story_30540601_99_dialog_content = "A-aku tidak lupa, kok! Aku hanya menaruhnya di sana sebentar.",
  ui_story_30540601_100_dialog_content = "Ha? Apa hakmu mengambil speaker milikku?!",
  ui_story_30540601_101_dialog_content = "Pipa-pipa aneh yang menonjol dari speaker-mu menyemburkan api! Itu sangat berbahaya!",
  ui_story_30540601_102_dialog_content = "Tapi, itu bagian dari pertunjukanku! Speaker itu kugunakan untuk efek spesialnya!",
  ui_story_30540601_103_dialog_content = "Sebentar, menurut buku panduan ini... GAYA RAMBUT-mu juga sangat berbahaya!",
  ui_story_30540601_104_dialog_content = "Aturan macam apa ini?!",
  ui_story_30540601_105_dialog_content = "Ketika pertama kali datang ke Colossus, tak ada yang menyebutkan aturan apa pun kepadaku! Kenapa tiba-tiba sekarang ada aturannya?!",
  ui_story_30540601_106_dialog_content = "T-tolong berhenti bertengkar! Begini saja...",
  ui_story_30540601_107_dialog_content = "Nadine, bisa tolong kembalikan speaker dan gergaji mereka dulu?",
  ui_story_30540601_108_dialog_content = "Tapi, aturannya jelas-jelas menyebutkan...",
  ui_story_30540601_109_dialog_content = "Aturan ini belum pernah diberlakukan secara resmi di Colossus sebelumnya.",
  ui_story_30540601_110_dialog_content = "Apa itu artinya... aku sudah melakukan kesalahan?",
  ui_story_30540601_111_dialog_content = "Sama sekali tidak! Hanya saja aturan ini harus sedikit disesuaikan dengan situasinya. Kamu tak perlu menelannya mentah-mentah.",
  ui_story_30540601_112_dialog_content = "Baiklah. Lagi pula kamulah Navigator-nya.",
  ui_story_30540601_113_dialog_content = "Kalau menurutmu begitu, aku akan mengikuti perintah...",
  ui_story_30540601_114_dialog_content = "Jadi, di mana barang-barang kami? Sini, kembalikan. Setelah itu kita lupakan masalah ini.",
  ui_story_30540601_115_dialog_content = "Ikutlah denganku. Akan kuantar kalian.",
  ui_story_30540601_116_dialog_content = "PlayerName... Aku justru memperburuk keadaan, ya?",
  ui_story_30540601_117_dialog_content = "*Ehem* Jangan terlalu dipikirkan.",
  ui_story_30540601_118_dialog_content = "Mengikuti aturan dengan cermat dan sungguh-sungguh seperti yang kamu lakukan juga terpuji.",
  ui_story_30540601_119_dialog_content = "Hanya saja situasinya jadi agak kacau.",
  ui_story_30540601_120_dialog_content = "Kurasa sebaiknya kita menghindari penyitaan barang siapa pun mulai sekarang.",
  ui_story_30540601_121_dialog_content = "Semua orang di Colossus peduli satu sama lain, dan tak akan pernah membahayakan nyawa orang lain.",
  ui_story_30540601_122_dialog_content = "Baiklah, sekarang aku mengerti!",
  ui_story_30540601_123_dialog_content = "Oh! Aku yakin kamu pasti haus setelah memberi penjelasan panjang lebar.",
  ui_story_30540601_124_dialog_content = "Mau minum? Aku bisa membuat minuman, terutama teh dan kopi.",
  ui_story_30540601_125_dialog_content = "Tidak, terima kasih. Aku tidak haus.",
  ui_story_30540601_125X1_dialog_content = "Tapi, rasanya aku harus melakukan sesuatu sebagai permintaan maaf... Bagaimana kalau kupijit bahumu?",
  ui_story_30540601_126_dialog_content = "Eh... M-mungkin aku minum kopi saja... Tolong tambahkan banyak susu dan gula, ya?",
  ui_story_30540601_127_dialog_content = "Bukan masalah! Kopinya akan segera datang!",
  ui_story_30540601_128_dialog_content = "Aku kembali, PlayerName...!",
  ui_story_30540601_129_dialog_content = "Aku suka bekerja, benar itu!",
  ui_story_30540601_130_dialog_content = "Ahhh!!",
  ui_story_30540601_131_dialog_content = "N-Nadine, kamu baik-baik saja?!",
  ui_story_30540601_132_dialog_content = "Aku... aku baik-baik saja... Tapi, kopimu...",
  ui_story_30540601_133_dialog_content = "Itu tidak penting! Ada yang sakit?",
  ui_story_30540601_134_dialog_content = "Tidak, tapi... Baju baruku...",
  ui_story_30540601_135_dialog_content = "Maafkan aku! Aku akan mencucinya sekarang!",
  ui_story_30540601_136_dialog_content = "Tidak apa-apa, nodanya hanya sedikit... *Menghela napas* Dia sudah pergi.",
  ui_story_30540601_137_dialog_content = "Argh...",
  ui_story_30540601_138_dialog_content = "Tidak apa-apa, Nadine. Bagian baju yang terkena tumpahan kopi hanya sedikit.",
  ui_story_30540601_139_dialog_content = "Tapi... Tapi, aku sudah berjanji tak akan mengotorinya!",
  ui_story_30540601_140_dialog_content = "Aku juga gagal dalam <color=#FFB400>tugas patroli</color>...",
  ui_story_30540601_141_dialog_content = "Itu hanya kesalahan kecil, Nadine! Mengalami masalah kecil seperti itu adalah hal yang wajar.",
  ui_story_30540601_142_dialog_content = "Selain itu, setelah melihatmu jatuh dan menumpahkan minuman ke tubuhmu sendiri... setidaknya aku sudah terbiasa.",
  ui_story_30540601_143_dialog_content = "Hah?! A-apa aku... benar-benar sekikuk itu...?",
  ui_story_30540601_144_dialog_content = "B-bukan begitu maksudku! Maksudku, kecanggunganmu yang sesekali muncul adalah salah satu sifat termanismu!",
  ui_story_30540601_145_dialog_content = "Nah, karena itu kamu tak perlu cemas.",
  ui_story_30540601_146_dialog_content = "Makin kamu berusaha menghiburku... makin aku merasa telah mengecewakan semua orang.",
  ui_story_30540601_147_dialog_content = "Kenapa? Itu kan hanya baju! Tapi... apa itu yang sebenarnya mengusikmu? Mengotori bajumu?",
  ui_story_30540601_148_dialog_content = "Benar... Seragam sangatlah penting.",
  ui_story_30540601_149_dialog_content = "Orang-orang memberiku seragam yang bagus... Mereka pasti berharap aku bekerja dengan lebih baik dari sebelumnya.",
  ui_story_30540601_150_dialog_content = "Sama sekali tidak! Kenapa kamu berpikir begitu?",
  ui_story_30540601_151_dialog_content = "Kurasa karena kebiasaan...",
  ui_story_30540601_152_dialog_content = "*Menghela napas* Kamu selalu bicara tentang kerja, bahkan saat sedang tidak bekerja...",
  ui_story_30540601_153_dialog_content = "Alasanku memberikan pakaian ini padamu adalah karena menurutku itu sangat cocok denganmu!",
  ui_story_30540601_154_dialog_content = "Selain itu, kupikir kalau aku memberimu pakaian yang lebih nyaman...",
  ui_story_30540601_155_dialog_content = "Kamu bisa <color=#FFB400>berhenti bekerja dan beristirahat</color> sedikit lebih lama.",
  ui_story_30540601_156_dialog_content = "Tak kusangka kamu akan menganggap serius tugas patroli ini seperti layaknya pekerjaanmu sendiri.",
  ui_story_30540601_157_dialog_content = "Begitu rupanya. Tapi, pakaian ini... Benar-benar untuk bersantai?",
  ui_story_30540601_158_dialog_content = "Eh... Baiklah. Aku tidak benar-benar yakin apakah ini lebih cocok untuk bersantai atau tidak...",
  ui_story_30540601_159_dialog_content = "Tapi, lihatlah! Pakaian ini ringan dan sejuk, dan tidak memiliki fitur-fitur pertahanan sama sekali.",
  ui_story_30540601_160_dialog_content = "Sepertinya agak lebih santai dari seragammu yang biasanya, 'kan?",
  ui_story_30540601_161_dialog_content = "K-kurasa begitu...",
  ui_story_30540601_162_dialog_content = "Omong-omong, mengerjakan apa pun dengan rajin memang bagus, tapi itu juga bisa membuatmu mengalami stres yang tidak perlu.",
  ui_story_30540601_163_dialog_content = "Jangan salah paham, bertugas juga bekerja. Tapi, selama kamu melakukan pemeriksaan secara berkala dan menyelesaikan patroli tepat waktu, itu sudah cukup.",
  ui_story_30540601_164_dialog_content = "Tidak perlu melakukannya dengan sangat serius.",
  ui_story_30540601_165_dialog_content = "Nah, karena pekerjaanku sudah selesai, mau kutunjukkan cara berpatroli dengan benar?",
  ui_story_30540601_166_dialog_content = "Baiklah!",
  ui_story_30540601_167_dialog_content = "Aku kembali! Apa terjadi sesuatu selama aku pergi, Nadine...?",
  ui_story_30540601_168_dialog_content = "\"Aku suka beristirahat, benar itu!\"",
  ui_story_30540601_169_dialog_content = "\"Aku suka beristirahat, bagaimana denganmu?\"",
  ui_story_30540601_170_dialog_content = "Kenapa para Firefly menyanyikan lagu yang aneh? Eh, sebentar... Apa mereka menari?!",
  ui_story_30540601_171_dialog_content = "Selamat datang kembali, Vice!",
  ui_story_30540601_172_dialog_content = "Nah, karena Vice sudah sangat berbaik hati menanyakannya...",
  ui_story_30540601_173_dialog_content = "Sebaiknya kita jawab dengan jujur!",
  ui_story_30540601_174_dialog_content = "Kami sedang berpatroli!",
  ui_story_30540601_175_dialog_content = "Dan karena kami berpatroli...",
  ui_story_30540601_176_dialog_content = "Untuk menjaga lingkungan yang damai dan penuh kasih di Colossus...",
  ui_story_30540601_177_dialog_content = "Kami telah memprogram ulang para Firefly untuk menyanyikan lagu baru!",
  ui_story_30540601_178_dialog_content = "Lagu yang akan membantu semua orang untuk beristirahat dan bersantai!",
  ui_story_30540601_179_dialog_content = "Ayo kita berusaha sebaik mungkin untuk bersantai, teman-teman!",
  ui_story_30540601_180_dialog_content = "<color=#e8d9bb>Nguuung!</color>",
  ui_story_30540601_181_dialog_content = "... Ada banyak hal yang tidak beres dengan situasi ini, aku bahkan tidak tahu harus mulai dari mana.",
  ui_story_30540602_1_dialog_content = "<color=#e8d9bb>Wuuss—</color>",
  ui_story_30540602_2_dialog_content = "Ahhh—Lenteraku tertiup angin!",
  ui_story_30540602_3_dialog_content = "Sial, andai saja aku tidak mendengarkan pedagang itu! Apa yang sebenarnya aku lakukan di sini, bermain-main di kolam air pasang ini?",
  ui_story_30540602_4_dialog_content = "...",
  ui_story_30540602_5_dialog_content = "Hei, aku melihat cahaya di sana! Lebih baik kita lihat.",
  ui_story_30540602_6_dialog_content = "...",
  ui_story_30540602_7_dialog_content = "Tunggu, sesuatu tentang gadis yang memegang lentera itu terasa aneh dan familiar.",
  ui_story_30540602_8_dialog_content = "Ini Nadine! Apa yang kamu lakukan di sini?",
  ui_story_30540602_9_dialog_content = "Navigator! Tunggu, seharusnya aku yang bertanya hal yang sama padamu, bukan?",
  ui_story_30540602_10_dialog_content = "Sebelumnya, kamu harus tahu—",
  ui_story_30540602_11_dialog_content = "Angin dan ombak di sini sangat kencang, dan tidak banyak tempat yang aman untuk menemukan pijakan yang mantap.",
  ui_story_30540602_12_dialog_content = "Satu langkah salah dan kamu bisa terjebak di lautan. Sebaiknya segera kembali secepatnya.",
  ui_story_30540602_13_dialog_content = "Aku tahu, aku tahu. Kamu tetap bertanggung jawab seperti biasa, Nadine.",
  ui_story_30540602_14_dialog_content = "Saya hanya tidak menyangka akan bertemu dengan Anda di Twin Pavilions Bay, itu saja...",
  ui_story_30540602_15_dialog_content = "Dan kamu terlihat agak berbeda dari biasanya...",
  ui_story_30540602_16_dialog_content = "Bisakah kamu ceritakan apa yang sedang kamu lakukan di sini?",
  ui_story_30540602_17_dialog_content = "Kamu memang gigih.",
  ui_story_30540602_18_dialog_content = "... Kurasa aku bisa memberitahumu tentang pekerjaan paruh waktuku—sebagai pemegang lentera.",
  ui_story_30540602_19_dialog_content = "Aspek terpenting dalam pekerjaanku adalah... menunggu.",
  ui_story_30540602_20_dialog_content = "Menunggu?",
  ui_story_30540602_21_dialog_content = "Ya. Kamu lihat cakrawala di sana? Mungkin terlalu gelap untuk melihatnya dengan jelas sekarang.",
  ui_story_30540602_22_dialog_content = "Tapi biasanya ada banyak kapal di sana. Banyak sekali.",
  ui_story_30540602_23_dialog_content = "Kapal dagang yang berlayar ke utara dan selatan, kapal nelayan yang menarik tangkapan besar, dan kapal wisata yang mengangkut penumpang yang antusias.",
  ui_story_30540602_24_dialog_content = "Rekan kerja dari shift sebelumnya mengatakan bahwa pengunjung sering melantunkan puisi saat menikmati pemandangan di sini.",
  ui_story_30540602_25_dialog_content = "Pasti sangat menenangkan bagi pikiran dan semangat.",
  ui_story_30540602_26_dialog_content = "Jadi, kamu sedang menunggu kapal-kapal itu?",
  ui_story_30540602_27_dialog_content = "Ya. Tugas saya adalah menunggu kembali setiap kapal yang berangkat dari sini.",
  ui_story_30540602_28_dialog_content = "Dan saat cuaca sangat buruk, tugasku juga untuk menerangi jalan mereka menuju keamanan!",
  ui_story_30540602_29_dialog_content = "Semakin menjadi alasan kamu harus kembali sekarang, Navigator. Berbahaya berada di luar saat cuaca seperti ini.",
  ui_story_30540602_30_dialog_content = "Mungkin bahkan ada badai yang sedang terjadi...",
  ui_story_30540602_31_dialog_content = "Kenapa kamu tidak ikut denganku, Nadine? Jika cuacanya seburuk ini, mungkin kamu juga seharusnya tidak bekerja.",
  ui_story_30540602_32_dialog_content = "Aku nggak bisa pergi. Belum saatnya.",
  ui_story_30540602_33_dialog_content = "Aku masih menunggu sesuatu...",
  ui_story_30540602_34_dialog_content = "Menunggu apa?",
  ui_story_30540602_35_dialog_content = "Untuk suara kapal-kapal yang kembali ke pelabuhan.",
  ui_story_30540602_36_dialog_content = "... Pernahkah kamu mengalami hal seperti ini, Navigator?",
  ui_story_30540602_37_dialog_content = "Ketika kamu menghabiskan satu hari penuh dalam keadaan fokus total, kamu mulai menyadari berbagai macam suara.",
  ui_story_30540602_38_dialog_content = "Seperti mendengar burung-burung terbang melintasi awan?",
  ui_story_30540602_39_dialog_content = "Ya, seperti itu.",
  ui_story_30540602_40_dialog_content = "Saat aku bekerja di terumbu karang ini, melihat semua perahu datang dan pergi...",
  ui_story_30540602_41_dialog_content = "Ombak membawa cerita-cerita dari kapal-kapal di laut.",
  ui_story_30540602_42_dialog_content = "Itu cukup tidak biasa...",
  ui_story_30540602_43_dialog_content = "Suatu kali, saya mendengar tentang bagaimana sebuah perahu nelayan terbalik dan awaknya terlempar ke laut.",
  ui_story_30540602_44_dialog_content = "Terima kasih, ada perahu penyelamat di dekat sana yang datang dan menarik semua orang keluar dari air.",
  ui_story_30540602_45_dialog_content = "Ketika para nelayan akhirnya tiba di darat, istri-istri mereka bereaksi dengan berbagai cara.",
  ui_story_30540602_46_dialog_content = "Beberapa dari mereka memeluk suami mereka dan menangis, sementara yang lain menyeret mereka pulang dengan menarik telinga.",
  ui_story_30540602_47_dialog_content = "Aku mengerti... Cerita-cerita seperti itu memang seperti awan: datang dalam berbagai bentuk dan ukuran.",
  ui_story_30540602_48_dialog_content = "Mereka dapat memberi tahu Anda banyak tentang dunia di sekitar kita, dan betapa cepatnya segala sesuatu dapat berubah.",
  ui_story_30540602_49_dialog_content = "Memang... Yah, angin semakin kencang. Sepertinya badai dahsyat sedang terjadi sekarang.",
  ui_story_30540602_50_dialog_content = "Kamu yakin nggak mau kembali? Masih ada waktu, lho...",
  ui_story_30540602_51_dialog_content = "Aku akan baik-baik saja. Ceritakan padaku kisah lain yang kamu dengar dari laut!",
  ui_story_30540602_52_dialog_content = "Ini akan membantu kita menghabiskan waktu!",
  ui_story_30540602_53_dialog_content = "Kisah-kisah tentang lautan pada umumnya sama saja. Aku tidak yakin orang-orang benar-benar tertarik untuk mendengarkannya.",
  ui_story_30540602_54_dialog_content = "Mengapa tidak kuceritakan sebuah kisah yang diceritakan kepadaku oleh orang lain? Tepatnya, rekan kerjaku.",
  ui_story_30540602_55_dialog_content = "Di tepi pantai negeri yang jauh, ada menara batu yang berbentuk seperti teratai.",
  ui_story_30540602_56_dialog_content = "Di kaki menara ini terdapat banyak singa kecil yang juga terbuat dari batu.",
  ui_story_30540602_57_dialog_content = "Menara yang jauh ini tidak terlalu tinggi atau indah. Menara ini juga tidak memancarkan cahaya keemasan.",
  ui_story_30540602_58_dialog_content = "Namun demikian, tempat ini memiliki tempat khusus di hati mereka yang tinggal di sekitarnya. Setiap kali mengalami kerusakan, pasti akan ada seseorang yang memperbaikinya.",
  ui_story_30540602_59_dialog_content = "Hingga saat ini, ia masih berdiri dengan megah di tepi laut. Seiring berjalannya waktu, banyak orang yang berdiri di puncak menara dengan lentera di tangan, seperti saya...",
  ui_story_30540602_60_dialog_content = "Memandu kapal-kapal yang tersesat menuju keamanan selama berabad-abad.",
  ui_story_30540602_61_dialog_content = "... Aku selalu menyukai cerita ini, terutama karena aku juga selalu membawa lentera kemana pun aku pergi.",
  ui_story_30540602_62_dialog_content = "Aku ingin terus menerangi jalan bagi orang lain, meskipun hanya untuk sedikit lebih lama.",
  ui_story_30540602_63_dialog_content = "... Angin semakin parah, Navigator... Bisakah kamu tetap berdiri?",
  ui_story_30540602_64_dialog_content = "Aku akan baik-baik saja.",
  ui_story_30540602_65_dialog_content = "Maka saya sarankan Anda mencari pijakan yang lebih baik. Setelah hujan mulai turun, mungkin saya tidak bisa menyelamatkan Anda.",
  ui_story_30540602_66_dialog_content = "Jangan khawatir, aku akan memikirkan sesuatu jika keadaan benar-benar memburuk.",
  ui_story_30540602_67_dialog_content = "Jika kamu sudah selesai dengan ceritamu, aku ingin berbagi salah satu ceritaku sendiri.",
  ui_story_30540602_68_dialog_content = "Suatu kali, ada seorang pengembara yang tiba di pantai Teluk Twin Pavilions. Saat mengamati kolam pasang, ia bertemu dengan seorang gadis muda dari Lumopolis.",
  ui_story_30540602_69_dialog_content = "Dia berpakaian ala Twin Pavilions Bay. Saat berjalan di tepi pantai, dia memegang sebuah lentera di tangannya.",
  ui_story_30540602_70_dialog_content = "Badai akan datang, tetapi dia menolak untuk meninggalkan posnya di atas terumbu karang yang besar.",
  ui_story_30540602_71_dialog_content = "Dia mendengarkan ombak sambil menunggu kapal-kapal pulang ke rumah.",
  ui_story_30540602_72_dialog_content = "Tidak ada mercusuar di sini, membuat tugasnya sangat penting menghadapi badai yang mendekat—sebagai pelindung dia.",
  ui_story_30540602_73_dialog_content = "Dia tidak hanya melindungi kapal-kapal di laut, tetapi juga para pengelana yang tersesat yang muncul di pantai!",
  ui_story_30540602_74_dialog_content = "Apa kamu...",
  ui_story_30540602_75_dialog_content = "Apakah Anda sedang memuji saya sekarang?",
  ui_story_30540602_76_dialog_content = "Aku tidak pernah merasa ada yang mengakui karyaku seperti ini!",
  ui_story_30540602_77_dialog_content = "Aku yakin semua orang merasa begitu tentang pekerjaanmu, meskipun mereka tidak mengatakannya.",
  ui_story_30540602_78_dialog_content = "Mendengarkan perahu yang datang dan pergi serta menerangi jalan pulang mereka...",
  ui_story_30540602_79_dialog_content = "Kamu sama pentingnya seperti mercusuar di mata mereka!",
  ui_story_30540602_80_dialog_content = "Hujan mulai turun.",
  ui_story_30540602_81_dialog_content = "Kamu benar-benar yakin tidak ingin kembali, Navigator?",
  ui_story_30540602_82_option_content = "Apa benar-benar perlu ditanya?",
  ui_story_30540602_83_option_content = "Tak bisa meninggalkan Lighthouse tanpa pengawasan, 'kan?",
  ui_story_30540602_84_dialog_content = "Navigator... Terima kasih.",
  ui_story_30540602_85_dialog_content = "Saya ingin mencoba sesuatu.",
  ui_story_30540602_86_dialog_content = "Menggunakan kekuatan saya untuk membantu sebanyak mungkin orang, meskipun hanya satu pengunjung pantai yang tersesat!",
  ui_story_30540602_87_dialog_content = "Cahaya... berkumpullah sekarang.",
  ui_story_30540602_88_dialog_content = "Di bawah lentera!",
  ui_story_30540602_89_dialog_content = "Langit mulai cerah.",
  ui_story_30540602_90_dialog_content = "Achoo! Ugh, sepertinya aku mungkin kena flu.",
  ui_story_30540602_91_dialog_content = "Masuk akal, karena kita berada di luar dalam hujan deras begitu lama.",
  ui_story_30540602_92_dialog_content = "Tetap saja, kita pasti telah membantu beberapa orang yang terjebak di laut, bukan?",
  ui_story_30540602_93_dialog_content = "Saya yakin kita berhasil. Setelah semua, laut terlihat jauh lebih ceria sekarang.",
  ui_story_30540602_94_dialog_content = "Laut itu hidup. Itu sesuatu yang akan selalu kuingat saat laut terlihat sedih.",
  ui_story_30540602_95_dialog_content = "Itulah mengapa aku ingin mengangkat lenteraku lebih tinggi. Setinggi mercusuar.",
  ui_story_30540602_96_dialog_content = "Kamu bisa melakukannya, Nadine! Jadi, kita bisa pulang sekarang?",
  ui_story_30540602_97_dialog_content = "Ya. Setelah kita kembali ke kota, aku akan mengenakan pakaian kering dan tidur siang yang lama dan nyaman...",
  ui_story_30540602_98_dialog_content = "Tunggu! Aku masih harus masuk kerja hari ini!",
  ui_story_30540602_99_dialog_content = "Aduh, jam berapa ini...?",
  ui_story_30540602_100_dialog_content = "Hah? Maksud kamu, kamu melakukan ini di atas pekerjaan Lumopolis biasa kamu?!",
  ui_story_30540602_101_dialog_content = "Itu terlalu berlebihan, bahkan untuk kamu! Kamu harus mengambil cuti sakit!",
  ui_story_30540602_102_dialog_content = "A-aku tidak bisa! Pekerjaan adalah pekerjaan. Membatalkan sama saja dengan menghindari tugas! Aku harus... Achoo!",
  ui_story_30540602_103_dialog_content = "Acho! Acho! Acho!",
